def trim_messages(messages, budget, count_tokens):
    items = list(messages or [])
    if not items:
        return [], 0
    system = items[0] if items[0].get('role') == 'system' else None
    body = items[1:] if system else items[:]

    def total(part):
        return count_tokens(([system] if system else []) + part)

    # 至少留一条，其余从最老的开始丢
    while len(body) > 1 and total(body) > budget:
        body.pop(0)
    # 剪完如果开头是 assistant，说明它的提问被删了，一起删掉
    while body and body[0].get('role') == 'assistant':
        body.pop(0)
    if total(body) > budget:
        # 一条都放不下：有 system 就只留 system，否则留最后一条
        body = [] if system else body[-1:]
    result = ([system] if system else []) + body
    if not result:
        result = [items[-1]]
    return result, len(items) - len(result)


def rough_tokens(messages):
    total = 0
    for message in messages:
        total += len(str(message.get('content', ''))) + 4
    return total


history = [{'role': 'system', 'content': '你是老师'}] + [
    {'role': 'user', 'content': f'问题{i}'} for i in range(1, 6)
]
history = [{'role': 'system', 'content': '你是老师'}]
for i in range(1, 6):
    history.append({'role': 'user', 'content': f'问题{i}的详细描述' * 2})
    history.append({'role': 'assistant', 'content': f'回答{i}的内容' * 2})
trimmed, dropped = trim_messages(history, 100, rough_tokens)
print('原有', len(history), '条，丢弃', dropped, '条')
for m in trimmed:
